import json
import sys
import types

NS = types.SimpleNamespace
invoice_text = ("ACME Supplies Ltd. Invoice for October services. "
                "Total due: 1,240.50 EUR by 2026-11-30.")


class BaseModel:
    def __init__(self, **data):
        self.__dict__.update(data)


_DATA = {"vendor": "ACME Supplies Ltd.", "number": None, "currency": "EUR",
         "total": 1240.5, "due_date": "2026-11-30"}


def _create(*, model, max_tokens, messages, **kwargs):
    loose = dict(_DATA, number="", total="1,240.50")
    block = NS(type="text", text=json.dumps(loose))
    return NS(content=[block], stop_reason="end_turn")


def _parse(*, model, max_tokens, messages, output_format, **kwargs):
    block = NS(type="text", text=json.dumps(_DATA))
    return NS(content=[block], stop_reason="end_turn",
              parsed_output=output_format(**_DATA))


class _Anthropic:
    def __init__(self, **kwargs):
        self.messages = NS(create=_create, parse=_parse)


sys.modules["anthropic"] = NS(Anthropic=_Anthropic)
sys.modules["pydantic"] = NS(BaseModel=BaseModel)
